const fs=require('node:fs'),ts=require('typescript'),vm=require('node:vm'),assert=require('node:assert/strict')
function load(path,imports={}){
  const js=ts.transpileModule(fs.readFileSync(path,'utf8'),{compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.CommonJS}}).outputText
  const exports={}
  vm.runInNewContext(js,{exports,require:n=>n in imports?imports[n]:require(n),Date,Number,Uint8Array,Error,console})
  return exports
}
const endereco=load('lib/enderecoObra.ts')
const regras=load('lib/contramarcoLocal.ts',{'./enderecoObra':endereco})
const base={nome_obra:' Casa 02 ',endereco:'Rua A, 5',cidade:'Outra cidade',observacoes:'Entrada lateral',gps:'-21.1,-49.4',updated_at:null}
assert.equal(regras.validarLocalContramarco(base).nome_obra,'Casa 02')
assert.equal(regras.validarLocalContramarco(base).gps,'-21.100000,-49.400000')
assert.throws(()=>regras.validarLocalContramarco({...base,nome_obra:' '}),/nome/)
assert.throws(()=>regras.validarLocalContramarco({...base,gps:'-91,0'}),/GPS/)
assert.throws(()=>regras.validarLocalContramarco({...base,updated_at:'invalid'}),/Versão/)
assert.throws(()=>regras.validarLocalContramarco({...base,observacoes:'x'.repeat(4001)}),/inválido/)
assert.equal(regras.assinaturaFotoContramarco(new Uint8Array([255,216,255,...Array(13).fill(0)]),'image/jpeg'),true)
assert.equal(regras.assinaturaFotoContramarco(new Uint8Array(24),'image/jpeg'),false)
assert.equal(regras.assinaturaFotoContramarco(new Uint8Array([137,80,78,71,13,10,26,10,...Array(8).fill(0)]),'image/png'),true)
assert.equal(regras.assinaturaFotoContramarco(new Uint8Array(Buffer.from('RIFF0000WEBP0000')),'image/webp'),true)
assert.equal(regras.assinaturaFotoContramarco(new Uint8Array(Buffer.from('0000ftypheic0000')),'image/heic'),true)
